                        err = c.get('is_error', False)
                        cont = str(c.get('content',''))[:150]
                        print(f'L{i}: RESULT err={err} {cont}')
            result = d.get('tool_use_result','')
            if 'Error' in str(result):
                print(f'L{i}: ERROR {str(result)[:200]}')
