            print(f'L{i}: SYSTEM {d.get(\"subtype\",\"\")}')
        elif t == 'result':
            print(f'L{i}: FINAL {d.get(\"subtype\",\"\")} error={d.get(\"is_error\",False)}')
    except:
        pass
